IF OBJECT_ID('[blackbaud].[spDeletetribute__blackbaud]', 'P') IS NOT NULL
    DROP PROCEDURE [blackbaud].[spDeletetribute__blackbaud];
GO

CREATE PROCEDURE [blackbaud].[spDeletetribute__blackbaud]
    @id nvarchar(450)
AS
BEGIN
    SET NOCOUNT ON;

    DELETE FROM
        [blackbaud].[tribute]
    WHERE
        [id] = @id


    -- Check if the delete was successful
    IF @@ROWCOUNT = 0
        SELECT NULL AS [id] -- Return NULL for all primary key fields to indicate no record was deleted
    ELSE
        SELECT @id AS [id] -- Return the primary key values to indicate we successfully deleted the record
END
GO
